import type { JSX, ReactNode } from "react";
import type {
  FieldErrors,
  RegisterOptions,
  UseFormProps,
  UseFormReturn,
} from "react-hook-form";
export type FormEngineMode = "multi-step" | "single";
export type FormEngineValidation = "per-step" | "on-submit";

/**
 * Plugins and step guards can return a plain boolean (true = pass) or a
 * structured result. When errors are returned, they are automatically
 * set on the form fields — no extra wiring required.
 *
 * @example
 * return { success: false, errors: { email: "This email is already taken." } }
 */
export type FormEngineValidateResult =
  | boolean
  | { success: false; errors: Record<string, string> };

/**
 * Plugins are the primary extension point. They hook into every lifecycle
 * event and can block navigation, surface errors, run analytics, etc.
 *
 * @example
 * plugins={[
 *   createZodPlugin(schemas),
 *   createAnalyticsPlugin((event, data) => mixpanel.track(event, data)),
 * ]}
 */
export type FormEnginePlugin = {
  name: string;
  onMount?: (values: Record<string, unknown>) => void;
  onStepChange?: (step: number, values: Record<string, unknown>) => void;
  onFieldChange?: (
    field: string,
    value: unknown,
    values: Record<string, unknown>,
  ) => void;
  /**
   * Return false or { success: false, errors } to block navigation.
   * Structured errors are automatically applied to the form fields.
   * Runs after per-step validation passes.
   */
  onValidate?: (
    step: number,
    values: Record<string, unknown>,
  ) => Promise<FormEngineValidateResult> | FormEngineValidateResult;
  onSubmit?: (values: Record<string, unknown>) => Promise<void>;
};

/**
 * Props passed into a custom render function.
 * Gives you full control over value, change handler, blur, error, and disabled.
 *
 * @example
 * {
 *   key: "color",
 *   variant: "custom",
 *   label: "Brand color",
 *   render: ({ value, onChange, error }) => (
 *     <ColorPicker value={value as string} onChange={onChange} error={error} />
 *   ),
 * }
 */
export type FieldRenderProps = {
  value: unknown;
  onChange: (value: unknown) => void;
  onBlur: () => void;
  error?: string;
  disabled: boolean;
};

export type TextInputProps = {
  icon?: React.ElementType;
  [x: string]: unknown;
};

export type FormEngineFieldVariant =
  | { variant: "text"; props?: TextInputProps; render?: never }
  | { variant: "number"; props?: TextInputProps; render?: never }
  | { variant: "email"; props?: TextInputProps; render?: never }
  | { variant: "password"; props?: TextInputProps; render?: never }
  | { variant: "textarea"; props?: TextInputProps; render?: never }
  | { variant: "tel"; props?: never; render?: TextInputProps }
  /**
   * Fully custom — you own the control.
   * The engine wires up value, onChange, error, and disabled for you.
   */
  | {
      variant: "custom";
      props?: never;
      render: (props: FieldRenderProps) => ReactNode;
    };

export type FormEngineFieldDef = {
  /** Must match a key in your form values. */
  key: string;
  label?: string;
  placeholder?: string;
  /**
   * Marks the field as required.
   * - true → "{{label}} is required"
   * - string → your custom message
   */
  required?: boolean | string;
  disabled?: boolean;
  className?: string;
  defaultValue?: unknown;
  /**
   * Additional react-hook-form validation rules (pattern, minLength, etc.).
   * Merged with the required rule if both are set.
   */
  rules?: Omit<RegisterOptions, "required">;
  /**
   * Conditionally show or hide this field based on current form values.
   * @example showWhen: (values) => values.plan === "pro"
   */
  showWhen?: (values: Record<string, unknown>) => boolean;
} & FormEngineFieldVariant;

export type FormEngineStepDef = {
  id: string;
  title?: string;
  description?: string;
  /**
   * Field definitions for config-driven rendering via FormEngineStepCanvas.
   * Omit when using FormEngineStep children for headless composition.
   */
  fields?: FormEngineFieldDef[];
  /**
   * Step-level validate function. Called before plugins.
   * Use this to wire in any form library — the engine doesn't care what's inside.
   *
   * @example — react-hook-form
   * validate: () => form.trigger(["name", "email"])
   *
   * @example — custom async check
   * validate: async () => {
   *   const ok = await checkUsername(values.username);
   *   return ok || false;
   * }
   */
  validate?: () => Promise<boolean> | boolean;
  /**
   * Async guard — called after validate() passes.
   * Return false to block navigation without showing an error (e.g. soft checks).
   */
  guard?: (values: Record<string, unknown>) => Promise<boolean> | boolean;
  /**
   * Custom layout for field-driven steps. Receives rendered fields and actions.
   *
   * @example
   * layout: (fields, actions) => (
   *   <div className="grid grid-cols-2 gap-8">
   *     <div>{fields}</div>
   *     <div className="mt-auto">{actions}</div>
   *   </div>
   * )
   */
  layout?: (fields: JSX.Element) => JSX.Element;
};

export type FormEngineConfig = {
  id?: string;
  mode?: FormEngineMode;
  validation?: FormEngineValidation;
  /** Custom react-hook-form resolver (e.g. zodResolver, yupResolver). */
  resolver?: UseFormProps["resolver"];
  /**
   * Full-form Zod schema applied on submit.
   * For per-step validation with field-level errors, use createZodPlugin().
   */
  schema?: any;
  steps: FormEngineStepDef[];
};

export type FormEngineFieldState = {
  visible: boolean;
  disabled: boolean;
};

export type FormDefaultValues = Record<number, Record<string, unknown>>;

export type FormEngineContextValue = {
  /** The react-hook-form instance. Exposed for advanced consumers. */
  form: UseFormReturn<Record<string, unknown>>;
  values: Record<string, unknown>;
  setFieldValue: (field: string, value: unknown) => void;

  currentStep: number;
  totalSteps: number;
  isFirstStep: boolean;
  isLastStep: boolean;
  goNext: () => Promise<void>;
  goBack: () => void;
  goTo: (step: number) => void;

  /** Computed visibility/disabled state per field key. */
  fieldState: Record<string, FormEngineFieldState>;

  isSubmitting: boolean;
  isValidating: boolean;
  errors: FieldErrors<Record<string, unknown>>;

  config: FormEngineConfig;
  plugins: FormEnginePlugin[];
};

export type FormEngineProps = {
  config: FormEngineConfig;
  defaultValues?: FormDefaultValues;
  plugins?: FormEnginePlugin[];
  onSubmit: (values: Record<string, unknown>) => Promise<void>;
  className?: string;
};

export type FormEngineRootProps = {
  config: FormEngineConfig;
  defaultValues?: FormDefaultValues;
  plugins?: FormEnginePlugin[];
  className?: string;
  children: ReactNode;
  onSubmit: (values: Record<string, unknown>) => Promise<void>;
};

import { cn } from "@/lib/utils";
import { FormEngineContext } from "./form-engine-context";
import { useFormEngineState } from "./form-engine-hook";
import {
  FormEngineProgress,
  FormEngineProgressProps,
} from "./form-engine-progress";
import {
  FormEngineStepMeta,
  FormEngineStepMetaProps,
} from "./form-engine-step-meta";
import { FormEngineStepCanvas } from "./form-engine-step-canvas";
import type { FormEngineProps } from "./types";
import {
  FormEngineNavigation,
  FormEngineNavigationProps,
} from "./form-engine-navigation";

interface FormEngineComponentProps extends FormEngineProps {
  className?: string;
  stepMetaProps?: FormEngineStepMetaProps;
  navigationProps?: FormEngineNavigationProps;
  stepProgressProps?: FormEngineProgressProps;
}

/**
 * FormEngine — batteries-included component.
 * Renders: progress dots → step title/description → fields → actions.
 *
 * Actions live inside FormEngineStepCanvas and animate with each step.
 * For full layout control, use FormEngineRoot instead.
 *
 * @example — simple usage
 * <FormEngine config={config} onSubmit={onSubmit} />
 *
 * @example — with zod validation
 * <FormEngine
 *   config={config}
 *   plugins={[createZodPlugin(schemas)]}
 *   onSubmit={onSubmit}
 * />
 *
 * @example — custom action layout
 * <FormEngine
 *   config={config}
 *   onSubmit={onSubmit}
 *   navigationProps={{ submitLabel: "Create account", layout: "split" }}
 * />
 */
export function FormEngine({
  config,
  plugins,
  defaultValues,
  className,
  stepMetaProps,
  navigationProps,
  stepProgressProps,
  onSubmit,
}: FormEngineComponentProps) {
  const engine = useFormEngineState({
    config,
    plugins,
    defaultValues,
    onSubmit,
  });

  return (
    <FormEngineContext.Provider value={engine}>
      <div className={cn("flex flex-col gap-6 w-full", className)}>
        <FormEngineProgress {...stepProgressProps} />
        <FormEngineStepMeta {...stepMetaProps} />
        <FormEngineStepCanvas />
        <FormEngineNavigation {...navigationProps} />
      </div>
    </FormEngineContext.Provider>
  );
}

FormEngine.displayName = "FormEngine";

import { cn } from "@/lib/utils";
import { FormEngineContext } from "./form-engine-context";
import { useFormEngineState } from "./form-engine-hook";
import type { FormEngineRootProps } from "./types";

/**
 * FormEngineRoot — provides the engine context without rendering any UI.
 * Use this when you want full control of the layout.
 *
 * @example
 * <FormEngineRoot config={config} plugins={[validationPlugin]}>
 *   <FormEngineStepMeta />
 *   <FormEngineStepCanvas />
 *   <FormEngineNavigation submitLabel="Create account" />
 * </FormEngineRoot>
 */
export function FormEngineRoot({
  config,
  plugins,
  defaultValues,
  className,
  children,
  onSubmit,
}: FormEngineRootProps) {
  const engine = useFormEngineState({
    config,
    plugins,
    onSubmit,
    defaultValues,
  });

  return (
    <FormEngineContext.Provider value={engine}>
      <div className={cn("flex flex-col gap-6 w-full", className)}>
        {children}
      </div>
    </FormEngineContext.Provider>
  );
}

FormEngineRoot.displayName = "FormEngineRoot";

import { createContext, useContext } from "react";
import type { FormEngineContextValue } from "./types";

export const FormEngineContext = createContext<FormEngineContextValue | null>(
  null,
);

/**
 * useFormEngineContext — access the form engine state from any child component.
 * Must be used inside <FormEngine> or <FormEngineRoot>.
 */
export function useFormEngineContext(): FormEngineContextValue {
  const ctx = useContext(FormEngineContext);
  if (!ctx) {
    throw new Error(
      "useFormEngineContext must be used within <FormEngine> or <FormEngineRoot>",
    );
  }
  return ctx;
}

import {
  useController,
  type Path,
  type RegisterOptions,
} from "react-hook-form";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { cn } from "@/lib/utils";
import { useFormEngineContext } from "./form-engine-context";
import type { FieldRenderProps, FormEngineFieldDef } from "./types";

/**
 * useFormEngineField — read and write a single field from within the engine.
 * Integrates with react-hook-form for validation and error messages.
 *
 * Pass RHF rules for validation beyond what the field config provides.
 */
export function useFormEngineField(key: string, rules?: RegisterOptions) {
  const ctx = useFormEngineContext();

  const { field, fieldState } = useController({
    name: key as Path<Record<string, unknown>>,
    control: ctx.form.control,
    rules,
  });

  return {
    value: field.value,
    onChange: (value: unknown) => {
      field.onChange(value);
      ctx.setFieldValue(key, value);
    },
    onBlur: field.onBlur,
    visible: ctx.fieldState[key]?.visible ?? true,
    disabled: ctx.fieldState[key]?.disabled ?? false,
    error: fieldState.error?.message,
  };
}

interface FormEngineFieldProps {
  field: FormEngineFieldDef;
}

export function FormEngineField({ field }: FormEngineFieldProps) {
  const rules: RegisterOptions = {
    ...(field.required
      ? {
          required:
            typeof field.required === "string"
              ? field.required
              : `${field.label ?? field.key} is required`,
        }
      : {}),
    ...(field.rules ?? {}),
  } as RegisterOptions;

  const { value, onChange, onBlur, visible, disabled, error } =
    useFormEngineField(field.key, rules);

  if (!visible) return null;

  if (field.variant === "custom") {
    const renderProps: FieldRenderProps = {
      value,
      onChange,
      onBlur,
      error,
      disabled,
    };

    return (
      <Field orientation="vertical" className={field.className}>
        {field.label && (
          <FieldLabel htmlFor={field.key}>
            {field.label}
            {field.required && (
              <span className="text-destructive ms-1" aria-hidden>
                *
              </span>
            )}
          </FieldLabel>
        )}
        {field.render(renderProps)}
        {error && <FieldError role="alert">{error}</FieldError>}
      </Field>
    );
  }

  const renderControl = () => {
    switch (field.variant) {
      case "text":
      case "email":
      case "number":
      case "tel":
      case "password": {
        const Icon = field.props?.icon;
        return (
          <InputGroup {...field.props}>
            <InputGroupInput
              id={field.key}
              type={field.variant}
              value={(value as string) ?? ""}
              onChange={(e) => onChange(e.target.value)}
              onBlur={onBlur}
              placeholder={field.placeholder}
              disabled={disabled}
              aria-invalid={!!error}
            />
            {Icon && (
              <InputGroupAddon align="inline-end">
                <Icon className="size-4 text-muted-foreground" />
              </InputGroupAddon>
            )}
          </InputGroup>
        );
      }
      default:
        return null;
    }
  };

  return (
    <Field className={cn(field.className)}>
      {field.label && (
        <FieldLabel htmlFor={field.key}>
          {field.label}
          {field.required && (
            <span className="text-destructive ms-1" aria-hidden>
              *
            </span>
          )}
        </FieldLabel>
      )}
      {renderControl()}
      {error && <FieldError role="alert">{error}</FieldError>}
    </Field>
  );
}

FormEngineField.displayName = "FormEngineField";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  useForm,
  type DefaultValues,
  type Path,
  type PathValue,
} from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import type {
  FormEngineConfig,
  FormEngineContextValue,
  FormEngineFieldState,
  FormEnginePlugin,
  FormEngineRootProps,
  FormEngineValidateResult,
} from "./types";

export interface UseFormEngineStateProps extends Pick<
  FormEngineRootProps,
  "config" | "plugins" | "onSubmit" | "defaultValues"
> {}

/**
 * useFormEngineState — the core logic hook.
 * Returns everything that goes into FormEngineContext.
 * Internal use only — consumers use useFormEngineContext().
 */
export function useFormEngineState({
  config,
  defaultValues,
  plugins = [],
  onSubmit,
}: UseFormEngineStateProps): FormEngineContextValue {
  const initialValues = useMemo<Record<string, unknown>>(() => {
    const vals: Record<string, unknown> = {};
    config.steps.forEach((step, index) => {
      step.fields?.forEach((field) => {
        vals[field.key] =
          field.defaultValue ?? defaultValues?.[index]?.[field.key];
      });
    });
    return vals;
  }, [config, defaultValues]);

  const form = useForm<Record<string, unknown>>({
    defaultValues: initialValues as DefaultValues<Record<string, unknown>>,
    resolver:
      config.resolver ??
      (config.schema ? zodResolver(config.schema as any) : undefined),
    mode: config.validation === "per-step" ? "onTouched" : "onSubmit",
  });

  const values = form.watch();
  const errors = form.formState.errors;
  const isSubmitting = form.formState.isSubmitting;

  const [currentStep, setCurrentStep] = useState(0);
  const [isValidating, setIsValidating] = useState(false);

  const allPlugins = useMemo(() => plugins ?? [], [plugins]);

  const mounted = useRef(false);
  useEffect(() => {
    if (!mounted.current) {
      mounted.current = true;
      allPlugins.forEach((p) => p.onMount?.(values));
    }
  }, []);

  const fieldState = useMemo<Record<string, FormEngineFieldState>>(() => {
    const state: Record<string, FormEngineFieldState> = {};
    config.steps.forEach((step) => {
      step.fields?.forEach((field) => {
        state[field.key] = {
          visible: field.showWhen ? field.showWhen(values) : true,
          disabled: field.disabled ?? false,
        };
      });
    });
    return state;
  }, [values, config]);

  const setFieldValue = useCallback(
    (field: string, value: unknown) => {
      form.setValue(
        field as Path<Record<string, unknown>>,
        value as PathValue<
          Record<string, unknown>,
          Path<Record<string, unknown>>
        >,
        { shouldDirty: true, shouldValidate: config.validation === "per-step" },
      );
      const next = form.getValues();
      allPlugins.forEach((p) => p.onFieldChange?.(field, value, next));
    },
    [form, allPlugins, config.validation],
  );

  /**
   * Resolves a FormEngineValidateResult.
   * When errors are returned, they are set on the RHF form automatically
   * so they surface in the field UI without any extra wiring.
   */
  const resolveValidation = useCallback(
    (result: FormEngineValidateResult): boolean => {
      if (typeof result === "boolean") return result;
      if (!result.success) {
        Object.entries(result.errors).forEach(([field, message]) => {
          form.setError(field as Path<Record<string, unknown>>, {
            type: "manual",
            message,
          });
        });
        return false;
      }
      return true;
    },
    [form],
  );

  const totalSteps = config.mode === "single" ? 1 : config.steps.length;
  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === totalSteps - 1;

  const goNext = useCallback(async () => {
    const step = config.steps[currentStep];
    setIsValidating(true);

    try {
      if (step.validate) {
        const valid = await step.validate();
        if (!valid) return;
      } else if (config.validation === "per-step" && step.fields?.length) {
        const stepFields = step.fields.map(
          (f) => f.key as Path<Record<string, unknown>>,
        );
        const valid = await form.trigger(stepFields);
        if (!valid) return;
      }

      if (step.guard) {
        const passed = await step.guard(form.getValues());
        if (!passed) return;
      }

      for (const plugin of allPlugins) {
        if (plugin.onValidate) {
          const result = await plugin.onValidate(currentStep, form.getValues());
          const passed = resolveValidation(result);
          if (!passed) return;
        }
      }

      if (isLastStep) {
        await form.handleSubmit(async (data) => {
          await onSubmit(data);
          for (const plugin of allPlugins) {
            await plugin.onSubmit?.(data);
          }
        })();
      } else {
        setCurrentStep((prev) => {
          const next = prev + 1;
          allPlugins.forEach((p) => p.onStepChange?.(next, form.getValues()));
          return next;
        });
      }
    } finally {
      setIsValidating(false);
    }
  }, [
    currentStep,
    isLastStep,
    config,
    allPlugins,
    form,
    resolveValidation,
    onSubmit,
  ]);

  const goBack = useCallback(() => {
    setCurrentStep((prev) => {
      const next = Math.max(0, prev - 1);
      allPlugins.forEach((p) => p.onStepChange?.(next, form.getValues()));
      return next;
    });
  }, [allPlugins, form]);

  const goTo = useCallback(
    (step: number) => {
      const clamped = Math.max(0, Math.min(step, totalSteps - 1));
      setCurrentStep(clamped);
      allPlugins.forEach((p) => p.onStepChange?.(clamped, form.getValues()));
    },
    [allPlugins, form, totalSteps],
  );

  return {
    form,
    values,
    setFieldValue,
    currentStep,
    totalSteps,
    isFirstStep,
    isLastStep,
    goNext,
    goBack,
    goTo,
    fieldState,
    isSubmitting,
    isValidating,
    errors,
    config,
    plugins: allPlugins,
  };
}

import { type ReactNode, type ComponentPropsWithoutRef } from "react";
import { Button } from "@/components/ui/button";
import {
  IconArrowLeft,
  IconLoader2,
  IconChevronRight,
  IconCheck,
} from "@tabler/icons-react";
import { motion, AnimatePresence } from "motion/react";
import { cn } from "@/lib/utils";
import { useFormEngineContext } from "./form-engine-context";

/**
 * stack   — full-width next, back centered below  (cards / modals)
 * split   — back left · next right                (drawers / panels)
 * compact — back icon-only on mobile · next right (wizards / full-page)
 */
export type FormEngineNavigationLayout = "stack" | "split" | "compact";

const LAYOUT_CLASS: Record<FormEngineNavigationLayout, string> = {
  stack: "flex-col items-center gap-3",
  split: "flex-row items-center justify-between gap-4",
  compact: "flex-row items-center justify-between gap-4",
};

export interface FormEngineNavigationProps {
  layout?: FormEngineNavigationLayout;
  className?: string;
  children?: ReactNode;
}

/**
 * Container. Accepts `layout` for the built-in back + next combo,
 * or `children` for full composition.
 *
 * @example built-in (zero config)
 * <FormEngineNavigation layout="split" />
 *
 * @example composed
 * <FormEngineNavigation layout="split">
 *   <FormEngineBackButton />
 *   <FormEngineNextButton submitLabel="Finish" />
 * </FormEngineNavigation>
 */
export function FormEngineNavigation({
  layout = "stack",
  className,
  children,
}: FormEngineNavigationProps) {
  const isStack = layout === "stack";
  const isSplit = layout === "split";

  return (
    <footer
      data-slot="form-engine-navigation"
      className={cn(
        "w-full flex transition-all duration-300",
        LAYOUT_CLASS[layout],
        className,
      )}
    >
      {children ?? (
        <>
          <FormEngineNextButton
            className={cn(
              isStack ? " w-full" : "order-2",
              isSplit && "ml-auto",
            )}
            fullWidth={isStack}
          />
          <FormEngineBackButton
            layout={layout}
            className={cn(isStack ? "w-full" : "order-1")}
            fullWidth={isStack}
          />
        </>
      )}
    </footer>
  );
}

FormEngineNavigation.displayName = "FormEngineNavigation";

// ─── Back Button ───────────────────────────────────────────────────────────────

export interface FormEngineBackButtonProps extends Omit<
  ComponentPropsWithoutRef<typeof Button>,
  "children"
> {
  label?: string;
  icon?: ReactNode;
  /** Collapse label to icon-only on mobile (compact layout) */
  iconOnly?: boolean;
  /** Hide when on the first step */
  hideOnFirst?: boolean;
  /** @internal used by FormEngineNavigation to set iconOnly per layout */
  layout?: FormEngineNavigationLayout;
  fullWidth?: boolean;
}

export function FormEngineBackButton({
  label = "Go back",
  icon,
  iconOnly,
  hideOnFirst = true,
  layout,
  fullWidth,
  className,
  ...props
}: FormEngineBackButtonProps) {
  const { isFirstStep, isSubmitting, isValidating, goBack } =
    useFormEngineContext();

  const busy = isSubmitting || isValidating;
  const hidden = isFirstStep && hideOnFirst;
  const collapseLabel = iconOnly ?? layout === "compact";

  return (
    <AnimatePresence mode="wait">
      {!hidden && (
        <motion.div
          key="back"
          initial={{ opacity: 0, x: -4 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -4 }}
          transition={{ duration: 0.15 }}
          data-slot="form-engine-back"
        >
          <Button
            size="lg"
            variant="secondary"
            type="button"
            disabled={isFirstStep || busy}
            onClick={goBack}
            aria-label={label}
            className={cn(
              "relative gap-2",
              fullWidth ? "w-full" : "w-full sm:w-auto sm:px-6",
              className,
            )}
            {...props}
          >
            {icon ?? <IconArrowLeft size={16} />}
            <span className={cn(collapseLabel && "hidden sm:inline")}>
              {label}
            </span>
          </Button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

FormEngineBackButton.displayName = "FormEngineBackButton";

export interface FormEngineNextButtonProps extends Omit<
  ComponentPropsWithoutRef<typeof Button>,
  "children"
> {
  nextLabel?: string;
  submitLabel?: string;
  loadingLabel?: string;
  nextIcon?: ReactNode;
  submitIcon?: ReactNode;
  loadingIcon?: ReactNode;
  loading?: boolean;
  /** Stretch to full container width */
  fullWidth?: boolean;
}

export function FormEngineNextButton({
  nextLabel = "Continue",
  submitLabel = "Complete",
  loadingLabel = "Processing...",
  nextIcon,
  submitIcon,
  loadingIcon,
  loading,
  fullWidth,
  className,
  ...props
}: FormEngineNextButtonProps) {
  const { isLastStep, isSubmitting, isValidating, goNext } =
    useFormEngineContext();

  const busy = isSubmitting || isValidating || !!loading;

  return (
    <Button
      data-slot="form-engine-next"
      size="lg"
      type="button"
      disabled={busy}
      onClick={goNext}
      className={cn(
        "relative gap-2",
        fullWidth ? "w-full" : "w-full sm:w-auto sm:px-6",
        className,
      )}
      {...props}
    >
      <AnimatePresence mode="wait">
        {busy ? (
          <motion.span
            key="loading"
            className="flex items-center gap-2"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.15 }}
          >
            {loadingIcon ?? <IconLoader2 size={16} className="animate-spin" />}
            {loadingLabel}
          </motion.span>
        ) : isLastStep ? (
          <motion.span
            key="submit"
            className="flex items-center gap-2"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.15 }}
          >
            {submitLabel}
            {submitIcon ?? <IconCheck size={16} />}
          </motion.span>
        ) : (
          <motion.span
            key="next"
            className="flex items-center gap-2"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.15 }}
          >
            {nextLabel}
            {nextIcon ?? <IconChevronRight size={16} />}
          </motion.span>
        )}
      </AnimatePresence>
    </Button>
  );
}

